sp_widget.client_script:
api.controller=function() {
  /* widget controller */
  var c = this;
};

sp_widget.css:
/* =========================================
   MAIN PAGE
========================================= */

.student-profile-page {

  width: 100%;
  max-width: 1080px;

  margin: 0 auto;

  padding: 28px 24px 60px;

  box-sizing: border-box;

  color: #102a56;

  font-family:
    -apple-system,
    BlinkMacSystemFont,
    "Segoe UI",
    Arial,
    sans-serif;

}


/* =========================================
   HEADER
========================================= */

.profile-header {

  background:
    linear-gradient(
      135deg,
      #f4f3ff,
      #eef1ff
    );

  border:
    1px solid #dfe3ff;

  border-radius: 18px;

  padding: 30px;

  margin-bottom: 24px;

  display: flex;

  justify-content: space-between;

  align-items: center;

  gap: 20px;

}


.eyebrow {

  font-size: 11px;

  font-weight: 700;

  letter-spacing: 1.8px;

  color: #5367ee;

}


.profile-header h1 {

  margin: 8px 0 6px;

  font-size: 29px;

  font-weight: 700;

  color: #092a5c;

}


.profile-header p {

  margin: 0;

  color: #71809c;

  font-size: 14px;

}


/* =========================================
   BUTTONS
========================================= */

.btn {

  display: inline-flex;

  align-items: center;

  justify-content: center;

  min-height: 40px;

  padding: 0 17px;

  border-radius: 9px;

  text-decoration: none !important;

  font-size: 13px;

  font-weight: 600;

  cursor: pointer;

  box-sizing: border-box;

}


.btn-secondary {

  background: #ffffff;

  border: 1px solid #cbd5e7;

  color: #40577c !important;

}


.btn-secondary:hover {

  background: #f5f7fb;

}


.btn-primary {

  background: #5367ee;

  border: 1px solid #5367ee;

  color: #ffffff !important;

}


/* =========================================
   PROFILE CARD
========================================= */

.profile-card {

  background: #ffffff;

  border:
    1px solid #e1e7f2;

  border-radius: 18px;

  overflow: hidden;

  box-shadow:
    0 7px 22px
    rgba(30,60,100,0.06);

}


/* =========================================
   STUDENT TOP
========================================= */

.student-top {

  padding: 28px;

  display: flex;

  align-items: center;

  gap: 18px;

  border-bottom:
    1px solid #edf0f6;

}


.student-avatar {

  width: 62px;

  height: 62px;

  border-radius: 15px;

  background: #5367ee;

  color: #ffffff;

  display: flex;

  align-items: center;

  justify-content: center;

  font-size: 24px;

  font-weight: 700;

  flex-shrink: 0;

}


.student-heading h2 {

  margin: 0 0 5px;

  font-size: 23px;

  color: #092c62;

}


.student-id {

  font-size: 12px;

  color: #71809c;

}


.student-status {

  margin-left: auto;

}


.status-badge {

  display: inline-flex;

  align-items: center;

  padding: 7px 14px;

  border-radius: 20px;

  background: #e8f8ef;

  color: #16834a;

  font-size: 12px;

  font-weight: 700;

}


/* =========================================
   SECTION
========================================= */

.section {

  padding: 28px;

  border-bottom:
    1px solid #edf0f6;

}


.section:last-child {

  border-bottom: none;

}


.section-title {

  font-size: 16px;

  font-weight: 700;

  color: #173b70;

  margin-bottom: 22px;

}


/* =========================================
   DETAILS
========================================= */

.details-grid {

  display: grid;

  grid-template-columns:
    repeat(2, 1fr);

  gap: 24px 45px;

}


.detail-item {

  display: flex;

  flex-direction: column;

  gap: 6px;

}


.detail-label {

  font-size: 10px;

  text-transform: uppercase;

  letter-spacing: 0.8px;

  color: #7a89a5;

  font-weight: 600;

}


.detail-value {

  font-size: 14px;

  color: #193964;

  font-weight: 600;

}


/* =========================================
   PLACEMENT
========================================= */

.placement-card {

  display: grid;

  grid-template-columns:
    repeat(2, 1fr);

  gap: 20px;

  background: #f8f9ff;

  border:
    1px solid #e4e8f8;

  border-radius: 12px;

  padding: 22px;

}


.placement-item {

  display: flex;

  flex-direction: column;

  gap: 7px;

}


.placement-value {

  font-size: 15px;

  font-weight: 700;

  color: #193964;

}


/* =========================================
   ERROR
========================================= */

.error-message {

  padding: 16px 18px;

  margin-bottom: 20px;

  background: #fff2f2;

  border:
    1px solid #ffd2d2;

  border-radius: 10px;

  color: #c62828;

  font-size: 13px;

  font-weight: 600;

}


/* =========================================
   NO STUDENT
========================================= */

.no-student {

  background: #ffffff;

  border:
    1px solid #e1e7f2;

  border-radius: 18px;

  min-height: 300px;

  display: flex;

  flex-direction: column;

  align-items: center;

  justify-content: center;

  text-align: center;

  padding: 40px;

}


.no-student-icon {

  width: 55px;

  height: 55px;

  border-radius: 14px;

  background: #eef1ff;

  display: flex;

  align-items: center;

  justify-content: center;

  font-size: 24px;

  margin-bottom: 15px;

}


.no-student h3 {

  margin: 0 0 8px;

  font-size: 18px;

  color: #102a56;

}


.no-student p {

  margin: 0 0 20px;

  color: #7a879d;

  font-size: 13px;

}


/* =========================================
   RESPONSIVE
========================================= */

@media (max-width: 700px) {

  .profile-header {

    flex-direction: column;

    align-items: flex-start;

  }


  .details-grid {

    grid-template-columns: 1fr;

  }


  .placement-card {

    grid-template-columns: 1fr;

  }


  .student-top {

    align-items: flex-start;

  }


  .student-status {

    margin-left: auto;

  }

}

sp_widget.script:
(function() {

    // =========================================
    // INITIALIZE
    // =========================================

    data.student = null;
    data.error = '';


    // =========================================
    // GET PARAMETERS
    // =========================================

    var interviewSysId =
        $sp.getParameter('interview_sys_id');

    var studentSysId =
        $sp.getParameter('sys_id');


    // =========================================
    // OPTION 1
    // DIRECT STUDENT SYS_ID
    // =========================================

    if (!studentSysId && interviewSysId) {

        /*
         * We came from the Interview Management page.
         *
         * Interview
         *    ↓
         * Student
         */

        var interviewGR =
            new GlideRecord(
                'x_snc_campus360_recruiter_interview'
            );


        if (
            interviewGR.get(interviewSysId)
        ) {

            studentSysId =
                interviewGR.getValue('student');

        } else {

            data.error =
                'Interview record could not be found.';

            return;

        }

    }


    // =========================================
    // VALIDATE STUDENT
    // =========================================

    if (!studentSysId) {

        data.error =
            'Student record was not specified.';

        return;

    }


    // =========================================
    // GET STUDENT RECORD
    // =========================================

    var studentGR =
        new GlideRecord(
            'x_snc_campus360_student_master'
        );


    if (
        !studentGR.get(studentSysId)
    ) {

        data.error =
            'Student record could not be found.';

        return;

    }


    // =========================================
    // BUILD STUDENT DATA
    // =========================================

    data.student = {

        // -------------------------------------
        // SYS ID
        // -------------------------------------

        sys_id:
            studentGR.getUniqueValue(),


        // -------------------------------------
        // STUDENT ID
        // -------------------------------------

        student_id:
            studentGR.getValue(
                'student_id'
            ),


        // -------------------------------------
        // STUDENT NAME
        // -------------------------------------

        student_name:
            studentGR.getValue(
                'student_name'
            ),


        // -------------------------------------
        // EMAIL
        // -------------------------------------

        email:
            studentGR.getValue(
                'email'
            ),


        // -------------------------------------
        // PHONE
        // -------------------------------------

        phone:
            studentGR.getValue(
                'phone_number'
            ),


        // -------------------------------------
        // BATCH
        // -------------------------------------

        batch:
            studentGR.getValue(
                'batch'
            ),


        // -------------------------------------
        // DEGREE
        // -------------------------------------

        degree:
            studentGR.getDisplayValue(
                'degree'
            ),


        // -------------------------------------
        // BRANCH
        // -------------------------------------

        branch:
            studentGR.getDisplayValue(
                'branch'
            ),


        // -------------------------------------
        // CGPA
        // -------------------------------------

        cgpa:
            studentGR.getValue(
                'cgpa'
            ),


        // -------------------------------------
        // BACKLOGS
        // -------------------------------------

        backlogs:
            studentGR.getValue(
                'backlogs'
            ),


        // -------------------------------------
        // PLACEMENT STATUS
        // -------------------------------------

        placement_status:
            studentGR.getDisplayValue(
                'placement_status'
            ),


        // -------------------------------------
        // PROFILE STATUS
        // -------------------------------------

        profile_status:
            studentGR.getDisplayValue(
                'profile_status'
            )

    };


})();
